export const masteryLevels = ['Not Started','Seen','Practiced','Can Use With Documentation','Can Use Independently','Can Explain','Mastered'];
const weekTags = [['python core'],['python internals'],['python core'],['async','asyncio'],['AI','agents'],['AI','architecture'],['RAG','database'],['production','reliability']];
const typingIds = new Set(['annotations','unions','callable-types','generics','protocol','typeddict','type-narrowing']);
const testingIds = new Set(['pytest','fixtures','parametrize','exception-tests','mocking','monkeypatch','fakes','test-boundaries','agent-tests','agent-evaluation','tool-evaluation','regression-eval','retrieval-eval']);
export const milestones = sections.flatMap((text,weekIndex)=>text.split('\n').map((line,index)=>{
 const [id,title,explanation,why,code,simple,practical,debugging,interview,prereqs,docKey]=line.split('|');
 const tags=[...weekTags[weekIndex]];
 if(typingIds.has(id))tags.push('typing');
 if(testingIds.has(id))tags.push('testing','evaluation');
 if(id.startsWith('fastapi'))tags.push('backend','FastAPI');
 if(docKey.startsWith('pydantic'))tags.push(weekIndex===4&&index<8?'Pydantic':'Pydantic AI');
 if(docKey.startsWith('ai-'))tags.push('Pydantic AI');
 if(id.startsWith('mcp'))tags.push('MCP');
 if(id.startsWith('tool')||id==='agent-tools')tags.push('tools','agents');
 if(id.startsWith('harness'))tags.push('harnesses','agents');
 if(id.startsWith('ontology'))tags.push('ontology','database');
 if(['tool-permissions','secrets','prompt-injection','human-approval','mcp-transport','metadata'].includes(id))tags.push('security');
 if(docKey.startsWith('dbos'))tags.push('DBOS','architecture');
 const checklist=['I read the concept','I implemented the examples myself','I completed the exercises without AI','I used documentation before asking AI','I can explain this concept','I completed the challenge'];
 return {id,title,week:weekIndex+1,order:index+1,explanation,why,prerequisites:prereqs?prereqs.split(','):[],difficulty:weekIndex===0?'Foundational':weekIndex<4?'Intermediate':'Advanced',officialDocumentation:docOverrides[id]||docs[docKey],additionalReading:{title:weekIndex<4?'Python language reference':'Related architecture and API reference',url:weekIndex<4?docs.model:weekIndex===4?docs['pydantic-ai']:weekIndex===5?docs.mcp:weekIndex===6?docs.fulltext:docs.otel},codeConcepts:code.split(',').map(x=>x.trim()),exercises:{simple:[simple,secondExercises[id]],practical,debugging},interviewQuestion:interview,explainQuestion:`Explain ${title.toLowerCase()} in your own words. Use a concrete example to show why this is true: ${explanation}`,checklist,tags:[...new Set(tags)],estimatedMinutes:weekIndex===0?25:weekIndex<4?40:55,masteryLevel:0,notes:''};
}));
export const milestoneById=Object.fromEntries(milestones.map(m=>[m.id,m]));
export const milestoneByTitle=Object.fromEntries(milestones.map(m=>[m.title,m]));
export function searchMilestones(query,{week,tag}={}){
 const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);
 return milestones.filter(m=>(!week||m.week===Number(week))&&(!tag||m.tags.includes(tag))&&words.every(word=>[m.title,m.explanation,m.codeConcepts.join(' '),m.tags.join(' '),`week ${m.week}`].join(' ').toLowerCase().includes(word)));
}
export function prerequisiteStatus(m,done){const missing=m.prerequisites.filter(id=>!done.includes(milestoneById[id].title));return {missing,ready:missing.length===0,total:m.prerequisites.length}}
export function ancestors(id){const found=new Set();function visit(current){for(const parent of milestoneById[current].prerequisites)if(!found.has(parent)){found.add(parent);visit(parent)}}visit(id);return found}

// Only map equivalent old outcomes. Broad category completion never auto-completes its children.
export const legacyAliases={'Variables':'Names, bindings, and references','References':'Names, bindings, and references','Shallow copy':'Shallow copy','Deep copy':'Deep copy','Equality vs. identity':'Equality versus identity','Shallow vs. deep copy':'Shallow copy','Mutable default arguments':'Mutable default parameters','args':'Collecting positional arguments with args','kwargs':'Collecting keyword arguments with kwargs','Scope':'Local and global scope','Closures':'Closures and captured bindings','Protocol':'Protocol and structural subtyping','TypedDict':'TypedDict for dictionary-shaped contracts','Decorators':'Applying a decorator','Generator':'Generator functions and yield','Iterator':'Iterators and StopIteration','Iterable':'Iterables and the iteration protocol'};
export function migrateCurriculum(saved){
 if(saved.curriculumVersion===2)return saved;
 const done=[...new Set(saved.done.flatMap(t=>[t,...(legacyAliases[t]?[legacyAliases[t]]:[])]))];
 const mastery={...saved.mastery};for(const [old,title] of Object.entries(legacyAliases))if(saved.mastery[old]!=null&&mastery[title]==null)mastery[title]=saved.mastery[old];
 const milestoneChecks={...saved.milestoneChecks},milestoneNotes={...saved.milestoneNotes};
 for(const m of milestones){
  const oldTitles=[m.title,...Object.entries(legacyAliases).filter(([,title])=>title===m.title).map(([old])=>old)];
  const checks={...milestoneChecks[m.id]};
  for(const item of m.checklist)if(checks[item]==null){const previous=oldTitles.find(title=>saved.checks?.[title+item]!=null);if(previous)checks[item]=saved.checks[previous+item]}
  if(Object.keys(checks).length)milestoneChecks[m.id]=checks;
  if(milestoneNotes[m.id]==null){const previous=oldTitles.find(title=>saved.solutions?.['reflection:'+title]);if(previous)milestoneNotes[m.id]='Earlier reflection:\n'+saved.solutions['reflection:'+previous]}
 }
 return {...saved,done,mastery,curriculumVersion:2,milestoneChecks,milestoneNotes,milestoneAnswers:saved.milestoneAnswers||{}};
}
